SELECT *
FROM monitor_sys_gen_alert_push_config
WHERE monitor_sys_gen_alert_push_config_enabled = 1
  AND monitor_sys_gen_alert_push_config_type = #{type}
  AND (
      monitor_sys_gen_server_id = #{serverId}
      OR monitor_sys_gen_server_id IS NULL
      OR monitor_sys_gen_server_id = 0
  )
ORDER BY update_time DESC
